package com.example.takura.quotations.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.takura.identity.application.PermissionService;
import com.example.takura.identity.domain.StaffPrincipal;
import com.example.takura.communications.application.OutboxWorker;
import com.example.takura.media.application.ObjectStoragePort;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.net.URI;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

@Testcontainers(disabledWithoutDocker = true)
class QuoteServicePostgresqlTest {
    @Container static final PostgreSQLContainer<?> POSTGRES = new PostgreSQLContainer<>("postgres:17.11-alpine3.24");
    static JdbcTemplate jdbc; static TransactionTemplate transactions; QuoteService service; QuoteSecretProtector protector; UUID estimator,approver,enquiry,pdf;
    final Instant now=Instant.parse("2026-10-21T08:00:00Z");

    @BeforeAll static void migrate(){var ds=new DriverManagerDataSource(POSTGRES.getJdbcUrl(),POSTGRES.getUsername(),POSTGRES.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/migration").defaultSchema("takura").schemas("takura").load().migrate();jdbc=new JdbcTemplate(ds);transactions=new TransactionTemplate(new DataSourceTransactionManager(ds));}
    @BeforeEach void setUp(){jdbc.execute("TRUNCATE takura.quote_outcome,takura.quote_access_attempt,takura.quote_access_session,takura.quote_delivery_secret,takura.customer_quote_grant,takura.quote_issue_command,takura.quote_revision,takura.quote_group,takura.operational_audit,takura.notification_outbox,takura.attachment_scan_job,takura.enquiry_attachment,takura.attachment,takura.upload_session,takura.enquiry_record_grant,takura.enquiry_service_detail,takura.enquiry,takura.staff_grant,takura.staff_team,takura.staff_role,takura.staff_session,takura.staff_identity CASCADE");
        estimator=identity("estimator");approver=identity("approver");enquiry=UUID.randomUUID();jdbc.update("INSERT INTO takura.enquiry(id,reference,state,team_code,owner_identity_id,full_name,email,preferred_contact,country_code,town_or_suburb,description,privacy_notice_version,privacy_acknowledged_at,created_at,first_response_due_at) VALUES(?,?,'QUOTE_IN_PREPARATION','BOARDS',?,'Synthetic Quote Customer','quote@example.invalid','EMAIL','ZA','Synthetic Area','Synthetic quote request','demo-v1',?,?,?)",enquiry,"DEMO-Q-"+enquiry.toString().substring(0,8),estimator,Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));
        UUID session=UUID.randomUUID();jdbc.update("INSERT INTO takura.upload_session(id,capability_hash,purpose,owner_identity_id,risk_hash,state,allocated_files,allocated_bytes,created_at,expires_at) VALUES(?,?,'STAFF_MEDIA',?,?,'COMPLETED',1,128,?,?)",session,"a".repeat(64),estimator,"b".repeat(64),Timestamp.from(now),Timestamp.from(now.plus(Duration.ofMinutes(60))));pdf=UUID.randomUUID();jdbc.update("INSERT INTO takura.attachment(id,upload_session_id,safe_display_name,extension,declared_content_type,expected_bytes,expected_checksum_sha256,staging_key,private_key,private_version,verified_checksum_sha256,state,created_at,completed_at,scan_completed_at,cleanup_eligible_at) VALUES(?,?,'synthetic-quote.pdf','pdf','application/pdf',128,?,'quarantine/test','private/test','v1',?,'CLEAN',?,?,?,?)",pdf,session,"c".repeat(64),"c".repeat(64),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now.plus(Duration.ofDays(30))));
        String key=Base64.getEncoder().encodeToString("0123456789abcdef0123456789abcdef".getBytes());protector=new QuoteSecretProtector(key);service=new QuoteService(jdbc,new PermissionService(),new MemoryStorage(),protector,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC),"Africa/Johannesburg","demo-quote-v1");}

    @Test void exactApprovalIssueExchangeAndRevocationLifecycle(){var draft=service.create(estimator(),enquiry,request("Synthetic reviewed board basis"));assertThat(draft.amount()).isEqualTo("2500.00");assertThat(draft.expiresAt()).isEqualTo(Instant.parse("2026-11-04T15:00:00Z"));var submitted=service.submit(estimator(),draft.id(),0);
        assertThatThrownBy(()->service.approve(principal(estimator,Set.of("enquiry:all:read","quote:approve")),draft.id(),submitted.revision())).isInstanceOf(ResponseStatusException.class).hasMessageContaining("SELF_APPROVAL_FORBIDDEN");
        var approved=service.approve(approver(),draft.id(),submitted.revision());var issue=service.issue(approver(),draft.id(),approved.revision(),"issue-1");var replay=service.issue(approver(),draft.id(),approved.revision(),"issue-1");assertThat(replay.customerUrl()).isEqualTo(issue.customerUrl());assertThat(jdbc.queryForObject("SELECT count(*) FROM takura.notification_outbox WHERE semantic_key=?",Integer.class,"quote-issue:"+draft.id())).isEqualTo(1);
        String token=issue.customerUrl().substring(issue.customerUrl().indexOf('#')+1);var exchange=service.exchange(token,"test-risk");assertThat(service.customer(exchange.session()).quoteNumber()).startsWith("Q-2026-");assertThat(service.document(exchange.session()).bytes()).isEqualTo("%PDF synthetic reviewed quote".getBytes());var worker=new OutboxWorker(jdbc,transactions,(template,recipient)->assertThat(recipient).endsWith("@example.invalid"),new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC),protector);assertThat(worker.runOnce()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT state FROM takura.enquiry WHERE id=?",String.class,enquiry)).isEqualTo("QUOTE_SENT");assertThat(jdbc.queryForObject("SELECT destroyed_at IS NOT NULL FROM takura.quote_delivery_secret WHERE quote_revision_id=?",Boolean.class,draft.id())).isTrue();service.revoke(approver(),draft.id(),"Synthetic revocation test");assertThatThrownBy(()->service.customer(exchange.session())).isInstanceOf(ResponseStatusException.class).hasMessageContaining("QUOTE_ACCESS_INVALID");}

    @Test void materialEditInvalidatesApprovalAndIssuedReplacementSupersedesOnlyOnIssue(){var first=approve(service.create(estimator(),enquiry,request("First basis")));var firstIssue=service.issue(approver(),first.id(),first.revision(),"first");var replacement=service.create(estimator(),enquiry,new QuoteService.CreateDraft(first.groupId(),pdf,new BigDecimal("2500.00"),"ZAR","NOT_APPLICABLE","Synthetic replacement scope",Map.of("basis","Replacement basis"),Map.of("terms","Synthetic reviewed terms"),Map.of("pdf_amount_matches",true,"terms_reviewed",true)));assertThat(service.get(estimator(),first.id()).state()).isEqualTo("ISSUED");
        var submitted=service.submit(estimator(),replacement.id(),0);var approved=service.approve(approver(),replacement.id(),submitted.revision());service.issue(approver(),replacement.id(),approved.revision(),"replacement");assertThat(service.get(estimator(),first.id()).state()).isEqualTo("SUPERSEDED");String old=firstIssue.customerUrl().substring(firstIssue.customerUrl().indexOf('#')+1);assertThatThrownBy(()->service.exchange(old,"old-link")).isInstanceOf(ResponseStatusException.class);
        var third=service.create(estimator(),enquiry,request("Third basis"));var awaiting=service.submit(estimator(),third.id(),0);var approvedThird=service.approve(approver(),third.id(),awaiting.revision());var edited=service.edit(estimator(),third.id(),approvedThird.revision(),request("Changed after approval"));assertThat(edited.state()).isEqualTo("DRAFT");assertThat(edited.approvedBy()).isNull();assertThatThrownBy(()->service.issue(approver(),third.id(),edited.revision(),"invalidated")).isInstanceOf(ResponseStatusException.class).hasMessageContaining("QUOTE_NOT_APPROVED");}

    @Test void acceptedExternalOutcomeRecordsEvidenceAndWonWithoutOnlineAcceptance(){jdbc.update("UPDATE takura.enquiry SET email=NULL,phone='000-synthetic',preferred_contact='CALL' WHERE id=?",enquiry);var issued=approve(service.create(estimator(),enquiry,request("Accepted basis")));service.issue(approver(),issued.id(),issued.revision(),"accepted");assertThat(jdbc.queryForObject("SELECT count(*) FROM takura.notification_outbox",Integer.class)).isZero();service.dispatch(approver(),issued.id(),"manual phone delivery evidence",true);assertThat(jdbc.queryForObject("SELECT state FROM takura.enquiry WHERE id=?",String.class,enquiry)).isEqualTo("QUOTE_SENT");service.outcome(approver(),issued.id(),new QuoteService.Outcome("ACCEPTED_EXTERNALLY","signed offline contract reference",now.plusSeconds(3600)));assertThat(jdbc.queryForObject("SELECT state FROM takura.enquiry WHERE id=?",String.class,enquiry)).isEqualTo("WON");}

    private QuoteService.QuoteView approve(QuoteService.QuoteView draft){var submitted=service.submit(estimator(),draft.id(),draft.revision());return service.approve(approver(),draft.id(),submitted.revision());}
    private QuoteService.CreateDraft request(String basis){return new QuoteService.CreateDraft(null,pdf,new BigDecimal("2500.00"),"ZAR","NOT_APPLICABLE","Synthetic reviewed scope",Map.of("basis",basis,"production_authorised",false),Map.of("terms","Synthetic reviewed terms"),Map.of("pdf_amount_matches",true,"terms_reviewed",true));}
    private UUID identity(String subject){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO takura.staff_identity(id,issuer,subject,display_label,active,provisioned_at,revocation_boundary) VALUES(?,'issuer',?,?,true,?,?)",id,subject,"Synthetic "+subject,Timestamp.from(now),Timestamp.from(now.minusSeconds(1)));return id;}
    private StaffPrincipal estimator(){return principal(estimator,Set.of("enquiry:all:read","quote:draft"));}private StaffPrincipal approver(){return principal(approver,Set.of("enquiry:all:read","quote:approve","quote:issue","quote:revoke","commercial:confirm"));}private StaffPrincipal principal(UUID id,Set<String> ops){return new StaffPrincipal(id,"issuer",id.toString(),"client",now,Set.of(),Set.of("BOARDS"),ops);}
    private static final class MemoryStorage implements ObjectStoragePort {public PresignedPost createUploadPost(String k,long b,String t,String c,String a,Duration d){throw new UnsupportedOperationException();}public StoredObject headStaging(String k){throw new UnsupportedOperationException();}public StoredObject pinToPrivate(String a,String b,String c){throw new UnsupportedOperationException();}public byte[] readPrivate(String k,String v){return "%PDF synthetic reviewed quote".getBytes();}public StoredObject writePublicDerivative(String k,byte[] b,String t){throw new UnsupportedOperationException();}public URI createPrivateDownload(String k,String v,Duration d){throw new UnsupportedOperationException();}public void deleteStaging(String k,String v){}public void deletePrivate(String k,String v){}public boolean privateExists(String k,String v){return true;}}
}
